  sessionId,
  createdAt: new Date('2026-01-01T00:00:00.000Z'),
  updatedAt: new Date('2026-01-01T00:02:00.000Z'),
  entryCount: 4,
});

// The same row as the wire frame describes it, so an assertion reads without knowing Date rendering.
