import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_CURSOR_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

// One validator per wire name, quoted because the wire's names are snake_case no identifier may carry.
const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validators[message.type];
  if (validate === undefined) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validate(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// The list is always the connection user's, so the validator takes no userId: it strips one instead.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = readLimit(message.limit);
  if ('error' in limit) return {valid: false, error: limit.error};

  const cursor = readCursor(message.before);
  if ('error' in cursor) return {valid: false, error: cursor.error};

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit.value !== undefined) frame.limit = limit.value;
  if (cursor.value !== undefined) frame.before = cursor.value;
  return {valid: true, data: frame};
}

// Reads the optional page size, refusing anything but a whole number from zero up.
function readLimit(value: unknown): {value?: number} | {error: string} {
  if (value === undefined) return {};
  if (!isNonNegativeInteger(value)) return {error: 'list_sessions limit must be a non-negative integer'};
  return {value};
}

// Reads the optional page cursor, refusing one that names no session or a time no calendar knows.
function readCursor(value: unknown): {value?: SessionCursor} | {error: string} {
  if (value === undefined) return {};
  if (typeof value !== 'object' || value === null) {
    return {error: 'list_sessions before must be a cursor object'};
  }

  const cursor = value as Record<string, unknown>;
  const sessionId = cursor.sessionId;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_CURSOR_SESSION_ID_LENGTH) {
    return {error: 'list_sessions before sessionId must be a string of 1 to 128 characters'};
  }

  if (!isParsableDate(cursor.updatedAt)) {
    return {error: 'list_sessions before updatedAt must be a parsable date'};
  }

  // Rebuilt from the two fields it defines, so anything else a client sent inside is dropped here.
  return {value: {updatedAt: cursor.updatedAt, sessionId}};
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

function isParsableDate(value: unknown): value is string | number {
  if (typeof value === 'number') return Number.isFinite(value);
  return typeof value === 'string' && !Number.isNaN(Date.parse(value));
}

